from wraptext import wrap


def test_overlong_words_are_truncated():
    assert wrap("a bbbbbbb", 5) == ["a", "bb..."]


def test_truncate_standalone():
    assert wrap("bbbbbbb", 3) == ["..."]


def test_exact_fit_line():
    assert wrap("aa bb", 5) == ["aa bb"]
